class AgentSink:
    """File-like wrapper that routes ``print``/``write`` output through
    :func:`agent_line`, line-buffered.

    The orchestrator hands an instance to ``worker.run_issue`` via its
    ``passthrough`` parameter so agent non-JSON output flows through the same
    Rich console as orchestrator events, with the ``│`` indent prefix. Tests
    that need to assert on raw agent output continue to pass an ``io.StringIO``
    instead.
    """

    def __init__(self) -> None:
        self._buf = ""

    def write(self, s: str) -> int:
        if not s:
            return 0
        self._buf += s
        while "\n" in self._buf:
            line, self._buf = self._buf.split("\n", 1)
            if line:
                agent_line(line)
        return len(s)

    def flush(self) -> None:
        if self._buf:
            agent_line(self._buf)
            self._buf = ""

    Returns ``None`` when the session finishes on its own first.
    """
    if token_limit is None and time_limit_seconds is None:
        wait(None)
        return None
    while True:
        if wait(poll_interval_seconds):
            return None
        if token_limit is not None:
            observed = accumulator.cumulative()
            if observed >= token_limit:
                return Breach("per-issue", "token", token_limit, observed)
        if time_limit_seconds is not None:
